def check(rxn, xyz):
    """Stereocentres outside the reaction centre keep their reactant handedness in the TS."""
    nb = rxn.neighbours('reactant')
    pnb = rxn.neighbours('product')
    tags = rxn.reactant_chiral_tags
    checked = 0

    def vol(c, ns, X):
        a, b, d = (X[k] - X[c] for k in ns[:3])
        return float(np.dot(a, np.cross(b, d)))

    for c in range(rxn.n):
        if tags[c] not in (1, 2) or c in rxn.reaction_centre:
            continue
        ns = list(nb.get(c, []))
        if len(ns) < 3 or len(ns) > 4:
            continue
        if list(pnb.get(c, [])) != ns:
            continue
        vr = vol(c, ns, rxn.reactant_xyz)
        if abs(vr) < 0.1:
            continue
        checked += 1
        vt = vol(c, ns, xyz)
        if vr * vt < 0 and abs(vt) > 0.1:
            return False, (f"{rxn.symbols[c]}{c + 1} stereocentre inverted: signed volume "
                           f"{vr:.2f} in reactant vs {vt:.2f} in TS")
    if checked == 0:
        return True, "rule not applicable"
    return True, f"{checked} spectator stereocentre(s) keep their handedness"

def check(rxn, xyz):
    """Each product stereocentre has the same signed volume sign at the TS as in the product geometry."""
    tags = rxn.product_chiral_tags
    centres = [i for i in range(rxn.n) if tags[i] in (1, 2)]
    if not centres:
        return True, "rule not applicable"
    nb = rxn.neighbours('product')
    pxyz = np.asarray(rxn.product_xyz, dtype=float)
    xyz = np.asarray(xyz, dtype=float)

    def vol(c, ns, pos):
        # normalised signed volume (triple product of unit vectors)
        if len(ns) == 4:
            vs = [pos[j] - pos[ns[0]] for j in ns[1:]]
        else:
            vs = [pos[j] - pos[c] for j in ns[:3]]
        vs = [v / (np.linalg.norm(v) + 1e-9) for v in vs]
        return float(np.dot(vs[0], np.cross(vs[1], vs[2])))

    checked = 0
    for c in centres:
        ns = list(nb.get(c, []))
        if len(ns) not in (3, 4):
            continue
        vp = vol(c, ns, pxyz)
        vt = vol(c, ns, xyz)
        if abs(vp) < 0.1:
            continue  # product reference is near-planar, handedness ill-defined
        checked += 1
        if abs(vt) < 0.05:
            continue  # TS centre essentially planar, no clear handedness either way
        if vp * vt < 0:
            return False, (f"{rxn.symbols[c]}{c + 1} stereocentre has inverted handedness at TS "
                           f"(TS volume {vt:+.2f}, product volume {vp:+.2f})")
    if checked == 0:
        return True, "rule not applicable"
    return True, f"{checked} product stereocentre(s) have product handedness at TS"

def check(rxn, xyz):
    """Non-reacting C=C/C=N/C=O double bonds and aromatic rings stay planar (max out-of-plane deviation <= 0.45 A)."""
    rn = rxn.neighbours('reactant')
    pn = rxn.neighbours('product')
    centre = set(rxn.reaction_centre)
    groups = []
    arom = []
    for (i, j), o in rxn.reactant_bonds.items():
        if rxn.product_bonds.get((i, j)) != o or i in centre or j in centre:
            continue
        if o == 2:
            groups.append(({i, j}, "double bond"))
        elif o == 1.5:
            arom.append((i, j))
    # merge aromatic bonds into connected rings/fused systems
    comps = []
    for i, j in arom:
        hit = [c for c in comps if i in c or j in c]
        new = {i, j}
        for c in hit:
            new |= c
            comps.remove(c)
        comps.append(new)
    groups += [(c, "aromatic ring") for c in comps]
    if not groups:
        return True, "rule not applicable"
    for core, kind in groups:
        if core & centre:
            continue
        pts = set(core)
        for a in core:
            for b in rn.get(a, []):
                if b in pn.get(a, []) and b not in centre:
                    pts.add(b)
        pts = sorted(pts)
        if len(pts) < 4:
            continue
        P = xyz[pts]
        P = P - P.mean(axis=0)
        normal = np.linalg.svd(P, full_matrices=False)[2][-1]
        dev = np.abs(P @ normal)
        k = int(np.argmax(dev))
        if dev[k] > 0.45:
            names = ",".join(rxn.symbols[a] + str(a + 1) for a in sorted(core))
            worst = rxn.symbols[pts[k]] + str(pts[k] + 1)
            return False, f"{kind} {names} is non-planar: {worst} is {dev[k]:.2f} A off the plane"
    return True, "spectator double bonds and aromatic rings are planar"

